47	  public static void assertTreesSortedAndMatch(ContainerProtos.ContainerMerkleTree expectedTree,
48	                                               ContainerProtos.ContainerMerkleTree actualTree) {
49	    assertEquals(expectedTree.getDataChecksum(), actualTree.getDataChecksum());
50	    assertEquals(expectedTree.getBlockMerkleTreeCount(), actualTree.getBlockMerkleTreeCount());
51	
52	    long prevBlockID = -1;
53	    for (int blockIndex = 0; blockIndex < expectedTree.getBlockMerkleTreeCount(); blockIndex++) {
54	      ContainerProtos.BlockMerkleTree expectedBlockTree = expectedTree.getBlockMerkleTree(blockIndex);
55	      ContainerProtos.BlockMerkleTree actualBlockTree = actualTree.getBlockMerkleTree(blockIndex);
56	
57	      // Blocks should be sorted by block ID.
58	      long currentBlockID = actualBlockTree.getBlockID();
59	      assertTrue(prevBlockID < currentBlockID);
60	      prevBlockID = currentBlockID;
61	
62	      assertEquals(expectedBlockTree.getBlockID(), actualBlockTree.getBlockID());
63	      assertEquals(expectedBlockTree.getBlockChecksum(), actualBlockTree.getBlockChecksum());
64	
65	      long prevChunkOffset = -1;
66	      for (int chunkIndex = 0; chunkIndex < expectedBlockTree.getChunkMerkleTreeCount(); chunkIndex++) {
67	        ContainerProtos.ChunkMerkleTree expectedChunkTree = expectedBlockTree.getChunkMerkleTree(chunkIndex);
68	        ContainerProtos.ChunkMerkleTree actualChunkTree = actualBlockTree.getChunkMerkleTree(chunkIndex);
69	
70	        // Chunks should be sorted by offset.
71	        long currentChunkOffset = actualChunkTree.getOffset();
72	        assertTrue(prevChunkOffset < currentChunkOffset);
73	        prevChunkOffset = currentChunkOffset;
74	
75	        assertEquals(expectedChunkTree.getOffset(), actualChunkTree.getOffset());
76	        assertEquals(expectedChunkTree.getLength(), actualChunkTree.getLength());
77	        assertEquals(expectedChunkTree.getChunkChecksum(), actualChunkTree.getChunkChecksum());
78	      }
79	    }
80	  }
