82	  /**
83	   * Builds a ChunkInfo object using the provided information. No new checksums are calculated, so this can be used
84	   * as either the leaves of pre-computed merkle trees that serve as expected values, or as building blocks to pass
85	   * to ContainerMerkleTree to have it build the whole tree from this information.
86	   *
87	   * @param indexInBlock Which chunk number within a block this is. The chunk's offset is automatically calculated
88	   *     from this based on a fixed length.
89	   * @param chunkChecksums The checksums within the chunk. Each is assumed to apply to a fixed value
90	   *     "bytesPerChecksum" amount of data and are assumed to be contiguous.
91	   * @return The ChunkInfo proto object built from this information.
92	   */
93	  public static ContainerProtos.ChunkInfo buildChunk(ConfigurationSource config, int indexInBlock,
94	                                                     ByteBuffer... chunkChecksums) {
95	    final long chunkSize = (long) config.getStorageSize(
96	        ScmConfigKeys.OZONE_SCM_CHUNK_SIZE_KEY, ScmConfigKeys.OZONE_SCM_CHUNK_SIZE_DEFAULT, StorageUnit.BYTES);
97	    final int bytesPerChecksum = config.getObject(OzoneClientConfig.class).getBytesPerChecksum();
98	
99	    // Each chunk checksum is added under the same ChecksumData object.
100	    ContainerProtos.ChecksumData checksumData = ContainerProtos.ChecksumData.newBuilder()
101	        .setType(ContainerProtos.ChecksumType.CRC32)
102	        .setBytesPerChecksum(bytesPerChecksum)
103	        .addAllChecksums(Arrays.stream(chunkChecksums)
104	            .map(ByteString::copyFrom)
105	            .collect(Collectors.toList()))
106	        .build();
107	
108	    return ContainerProtos.ChunkInfo.newBuilder()
109	            .setChecksumData(checksumData)
110	            .setChunkName("chunk")
111	            .setOffset(indexInBlock * chunkSize)
112	            .setLen(chunkSize)
113	            .build();
114	  }
